const USERS = [93913];
const START = '2026-08-20';
const END = '2026-08-27';
const EVENTS = ['translation.updated', 'translations.updated'];
function iso(d) { return d.toISOString().slice(0, 10); }
const out = [];
for (const u of USERS) {
  for (const ev of EVENTS) {
    let cur = new Date(START + 'T00:00:00Z');
    const endD = new Date(END + 'T00:00:00Z');
    while (cur.getTime() <= endD.getTime()) {
      out.push({ json: { user_id: u, event_type: ev, date_from: iso(cur), date_to: iso(cur) } });
      cur = new Date(cur.getTime() + 86400000);
    }
  }
}
return out;

const projRes = $('Fetch Lokalise Projects').first().json;
const projects = projRes.projects || (projRes.body && projRes.body.projects) || [];
const nameById = {};
for (const p of projects) { nameById[String(p.project_id)] = p.name; }

const reqs = $('Build Audit Requests').all();
const res = $input.all();
const byProject = {};
const events = [];
const failed = [];
const more = [];
const statuses = {};
let total = 0;

function trunc(s) {
  if (typeof s !== 'string') { return s === null || s === undefined ? '' : String(s); }
  return s.length > 400 ? s.slice(0, 400) + '\u2026' : s;
}
function projectOf(ev) {
  for (const e of (ev.enrichments || [])) {
    if ((e.name || '') === 'project' && e.data && e.data.id) { return String(e.data.id); }
  }
  return null;
}

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  const meta = metaItem ? metaItem.json : {};
  const r = res[i].json || {};
  const body = r.body || {};
  statuses[String(r.statusCode)] = (statuses[String(r.statusCode)] || 0) + 1;
  if (r.statusCode !== 200) { failed.push(meta.event_type + '/' + meta.date_from + ' -> ' + r.statusCode); continue; }
  if (body.has_more) { more.push(meta.event_type + '/' + meta.date_from); }
  for (const ev of (body.data || [])) {
    total++;
    const pid = projectOf(ev);
    const pname = pid ? (nameById[pid] || 'unknown') : 'no-project';
    const bk = pid + ' | ' + pname;
    byProject[bk] = (byProject[bk] || 0) + 1;
    if (!/realchecker/i.test(pname)) { continue; }
    const d = (ev.unmapped && ev.unmapped.data) ? ev.unmapped.data : (ev.data || {});
    if (d.translations && d.translations.length) {
      for (const t of d.translations) {
        events.push({ ts: ev.time, project_id: pid, project_name: pname, bulk: true, lang_id: (t.language && t.language.id) ? t.language.id : null, lang_iso: (t.language && t.language.iso) ? t.language.iso : null, key_id: (t.key && t.key.id) ? t.key.id : null, key_name: (t.key && t.key.name) ? t.key.name : null, old: trunc(t.previous_value), neu: trunc(t.value) });
      }
    } else {
      events.push({ ts: ev.time, project_id: pid, project_name: pname, bulk: false, lang_id: d.lang_id === undefined ? null : d.lang_id, lang_iso: d.lang_iso === undefined ? null : d.lang_iso, key_id: d.key_id === undefined ? null : d.key_id, key_name: d.key === undefined ? null : d.key, old: trunc(d.old_translation), neu: trunc(d.new_translation) });
    }
  }
}

events.sort(function (a, b) { return Number(a.ts) - Number(b.ts); });
const projectList = [];
for (const p of projects) { projectList.push({ id: p.project_id, name: p.name }); }

return [{ json: { total_events_all_projects: total, by_project: byProject, statuses: statuses, failed: failed, has_more_windows: more, realchecker_event_count: events.length, all_projects: projectList, events: events } }];
